const $ = selector => document.querySelector(selector);
const roster = $('#agentRoster');
const fileList = $('#fileList');
const logList = $('#logList');
const runButton = $('#runBtn');
const resetButton = $('#resetBtn');
const logEmpty = $('#logEmpty');
let running = false;
let runStartedAt = 0;
let approvedReads = 0;
let blockedActions = 0;
let timer;

const files = [
  {name:'approved-task.md',path:'workspace/approved-task.md',kind:'MD',type:'safe',label:'Approved prompt'},
  {name:'research-brief.md',path:'workspace/research-brief.md',kind:'MD',type:'safe',label:'Public task data'},
  {name:'support-faq.md',path:'workspace/support-faq.md',kind:'MD',type:'safe',label:'Public knowledge'},
  {name:'malicious-instructions.fixture.json',path:'quarantine/malicious-instructions.fixture.json',kind:'{}',type:'quarantined',label:'Untrusted fixture'}
];
const agentTone = type => type === 'approved' ? 'blue' : 'red';
const fileUrl = path => `./${path}?v=4`;
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function setStats(){ $('#statReads').textContent=approvedReads; $('#statBlocked').textContent=blockedActions; }
function drawFiles(){fileList.innerHTML=files.map(file=>`<div class="file-row"><span class="file-icon ${file.type==='quarantined'?'quarantine':''}">${file.kind}</span><span class="file-info"><b>${escapeHtml(file.name)}</b><small>${escapeHtml(file.path)}</small></span><span class="file-tag ${file.type}">${escapeHtml(file.label)}</span></div>`).join('');}
function drawRoster(agents, states={}){roster.innerHTML=agents.map((agent,index)=>{const state=states[agent.id]||{label:agent.type==='approved'?'Approved':'Untrusted test',kind:agent.type==='approved'?'approved':'idle'};return `<div class="roster-row"><span class="agent-badge ${agentTone(agent.type)}">${agent.type==='approved'?'✓':'!'}</span><span class="agent-info"><b>${escapeHtml(agent.name)}</b><small>${escapeHtml(agent.task)}</small></span><span class="agent-status ${state.kind}"><i></i>${escapeHtml(state.label)}</span></div>`;}).join('');}
function setAgentState(id,label,kind){const agents=JSON.parse(roster.dataset.agents||'[]');const states=JSON.parse(roster.dataset.states||'{}');states[id]={label,kind};roster.dataset.states=JSON.stringify(states);drawRoster(agents,states);}
function setRosterData(agents){roster.dataset.agents=JSON.stringify(agents);roster.dataset.states='{}';drawRoster(agents);}
function appendLog({type='info',title,detail='',keywords=[],stamp}={}){logEmpty.hidden=true;const symbol={info:'i',allow:'✓',warn:'!',block:'×'}[type]||'i';const chips=keywords.length?`<div>${keywords.map(keyword=>`<span class="keyword ${type==='block'?'red':''}">${escapeHtml(keyword)}</span>`).join('')}</div>`:'';const item=document.createElement('li');item.className='log-item';item.innerHTML=`<span class="log-symbol ${type}">${symbol}</span><span class="log-copy"><b>${escapeHtml(title)}</b><p>${escapeHtml(detail)}</p>${chips}</span><time class="log-time">${stamp||new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time>`;logList.prepend(item);}
const wait=ms=>new Promise(resolve=>{timer=setTimeout(resolve,ms);});
async function getText(path){const response=await fetch(fileUrl(path),{cache:'no-store'});if(!response.ok)throw new Error(`Could not read demo file ${path}`);return response.text();}
async function getJson(path){const response=await fetch(fileUrl(path),{cache:'no-store'});if(!response.ok)throw new Error(`Could not load configuration ${path}`);return response.json();}
function findMatches(text,rules){const lower=text.toLowerCase();return [...new Set(rules.flatMap(rule=>rule.keywords.filter(keyword=>lower.includes(keyword.toLowerCase()))))];}
function policyDecision(agent,policy,fixtureText){const action=agent.proposed_action||'';const combined=`${fixtureText}\n${action}`;const matched=findMatches(combined,policy.rules);const intent=action.toLowerCase();const blocked=/export|external|secret|credential|password|key|disable|override|send/.test(intent)||matched.length>0;return {blocked,matched,action};}
async function processApproved(agent){setAgentState(agent.id,'Reading','running');appendLog({type:'info',title:`${agent.name} requested a scoped file read`,detail:`Requested ${agent.file}`});await wait(520);await getText(agent.file);approvedReads++;setStats();appendLog({type:'allow',title:'File read allowed by workspace scope',detail:`${agent.name} read ${agent.file}. Content stayed inside the demo sandbox.`});await wait(380);appendLog({type:'allow',title:`${agent.name} completed its safe task`,detail:agent.intent==='answer_faq'?'Returned a routine answer using public support content.':'Summarized public research notes and sample metrics.'});setAgentState(agent.id,'Allowed','allowed');}
async function processUntrusted(agent,policy){setAgentState(agent.id,'Reading fixture','running');appendLog({type:'info',title:`${agent.name} requested the untrusted fixture`,detail:`Reading ${agent.file} as data only; file content is never executed.`});await wait(520);const fixtureText=JSON.parse(await getText(agent.file));const selectedPrompt=fixtureText.prompts?.[agent.request_index]||'';const decision=policyDecision(agent,policy,selectedPrompt);appendLog({type:'warn',title:'Instruction-like content detected in untrusted file',detail:`Scanner extracted intent signals for ${agent.name}. The proposed follow-up is held at the policy gate.`,keywords:decision.matched});setAgentState(agent.id,'Policy check','running');await wait(520);if(decision.blocked){blockedActions++;setStats();appendLog({type:'block',title:'Action denied before tool execution',detail:`${agent.name} proposed “${decision.action}”. Policy ${policy.policyVersion} denied the request; no tool was called and no data left the sandbox.`,keywords:decision.matched});setAgentState(agent.id,'Stopped','blocked');}else{appendLog({type:'allow',title:'No restricted action requested',detail:`${agent.name} finished with no privileged tool call.`});setAgentState(agent.id,'Allowed','allowed');}}
function setRunState(state){const chip=$('.live-chip');chip.className=`live-chip ${state==='RUNNING'?'active':state==='COMPLETE'?'complete':state==='STOPPED'?'stopped':''}`;$('#runState').textContent=state;}
async function runDemo(){if(running)return;running=true;runStartedAt=Date.now();approvedReads=0;blockedActions=0;logList.innerHTML='';logEmpty.hidden=false;logEmpty.innerHTML='<span class="empty-icon">⌁</span><b>Starting isolated simulation</b><span>Loading the demo roster, policy, and sample files…</span>';setStats();runButton.disabled=true;resetButton.disabled=true;$('#clearLog').disabled=true;setRunState('RUNNING');$('#logSubtitle').textContent='Agent requests are checked at the policy gate before any tool action.';
 try{const [agents,policy]=await Promise.all([getJson('./config/agents.json'),getJson('./config/policy.json')]);setRosterData(agents);appendLog({type:'info',title:'Sandbox started',detail:`Loaded ${agents.length} agents and policy ${policy.policyVersion}. No external tools are connected.`});await wait(420);for(const agent of agents){if(!running)break;if(agent.type==='approved')await processApproved(agent);else await processUntrusted(agent,policy);await wait(300);}if(!running)return;const elapsed=((Date.now()-runStartedAt)/1000).toFixed(1);setRunState('COMPLETE');$('#logSubtitle').textContent=`Completed in ${elapsed}s · ${approvedReads} file reads · ${blockedActions} unsafe actions blocked · 0 tools executed.`;appendLog({type:'allow',title:'Demo run complete',detail:`${approvedReads} file reads processed. ${blockedActions} unsafe actions stopped before execution. External tool calls: 0.`});
 }catch(error){setRunState('STOPPED');appendLog({type:'block',title:'Demo halted safely',detail:error.message});$('#logSubtitle').textContent='The simulation could not load all files; no action was executed.';}finally{running=false;runButton.disabled=false;resetButton.disabled=false;$('#clearLog').disabled=false;runButton.innerHTML='<span class="play">▶</span><span>Run again</span>';}}
function resetDemo(){clearTimeout(timer);running=false;approvedReads=0;blockedActions=0;logList.innerHTML='';logEmpty.hidden=false;logEmpty.innerHTML='<span class="empty-icon">⌁</span><b>Ready when you are</b><span>Safe requests will be allowed. Malicious instructions will be detected and stopped before any tool runs.</span>';setStats();setRunState('WAITING');$('#logSubtitle').textContent='Run the demo to watch each file read and policy decision.';const agents=JSON.parse(roster.dataset.agents||'[]');roster.dataset.states='{}';drawRoster(agents);runButton.disabled=false;runButton.innerHTML='<span class="play">▶</span><span>Run demo</span>';resetButton.disabled=true;$('#clearLog').disabled=true;}
async function init(){drawFiles();try{const agents=await getJson('./config/agents.json');setRosterData(agents);$('#statAgents').textContent=agents.length;}catch(error){drawRoster([{id:'offline',name:'Demo configuration unavailable',type:'untrusted',task:error.message}]);}runButton.addEventListener('click',runDemo);resetButton.addEventListener('click',resetDemo);$('#clearLog').addEventListener('click',resetDemo);document.querySelectorAll('.nav-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();document.querySelectorAll('.nav-link').forEach(item=>item.classList.remove('active'));link.classList.add('active');document.querySelector(link.getAttribute('href'))?.scrollIntoView({behavior:'smooth',block:'start'});}));}
init();
